public int[] DailyTemperaturesBrute(int[] temperatures)
{
    int n = temperatures.Length;
    var answer = new int[n];

    for (int i = 0; i < n; i++)
    {
        for (int j = i + 1; j < n; j++)
        {
            if (temperatures[j] > temperatures[i])
            {
                answer[i] = j - i;
                break;
            }
        }
    }

    return answer;
}

public int[] DailyTemperatures(int[] temperatures)
{
    int n = temperatures.Length;
    var answer = new int[n];
    var stack = new Stack<int>(); // indices, decreasing temperature

    for (int i = 0; i < n; i++)
    {
        // Resolve every day that is colder than today
        while (stack.Count > 0 && temperatures[stack.Peek()] < temperatures[i])
        {
            int colderDay = stack.Pop();
            answer[colderDay] = i - colderDay;
        }

        stack.Push(i);
    }

    // Days left on the stack have no warmer day ahead - answer stays 0
    return answer;
}

public int[] DailyTemperatures(int[] temperatures)
{
    int n = temperatures.Length;
    var answer = new int[n];
    var stack = new Stack<int>();

    for (int i = 0; i < n; i++)
    {
        while (stack.Count > 0 && temperatures[stack.Peek()] < temperatures[i])
        {
            int colderDay = stack.Pop();
            answer[colderDay] = i - colderDay;
        }
        stack.Push(i);
    }

    return answer;
}
